import { Box, Container, Stack, Typography } from "@mui/material";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { HomeApp } from "../types/home";

export default function AppDownload({ data }: { data?: HomeApp | null }) {
  if (!data) return null;

  return (
    <Box sx={{ py: { xs: 4, sm: 6, md: 8, lg: 10, tv: 12 }, backgroundColor: "#f5fafe" }}>
      <Container
        maxWidth={false}
        sx={{ px: { xs: 2, sm: 3, md: 5, tv: 8 }, maxWidth: { xs: "100%", md: "90%", tv: 1680 } }}
      >
        <Stack
          direction={{ xs: "column", lg: "row" }}
          alignItems="center"
          spacing={{ xs: 3, sm: 4, lg: 0 }}
        >
          <Box sx={{ width: { xs: "100%", lg: "40%" }, pr: { lg: 4 } }}>
            <Typography
              sx={{
                color: "#17224d",
                fontSize: { xs: 22, sm: 26, md: 32, lg: 35, tv: 42 },
                fontWeight: 600,
                mb: 2,
              }}
            >
              {data.title}
            </Typography>
            <BlocksText
              content={data.description}
              sx={{ color: "#5a6473", fontSize: { xs: 14, sm: 15, md: 16, tv: 18 }, mb: 3 }}
            />
            <Stack direction="row" spacing={{ xs: 1.25, md: 2 }} flexWrap="wrap" useFlexGap sx={{ mb: 3 }}>
              {data.appStoreUrl && mediaUrl(data.appStoreImage) ? (
                <Box component="a" href={data.appStoreUrl} target="_blank" rel="noopener noreferrer">
                  <Box
                    component="img"
                    src={mediaUrl(data.appStoreImage)}
                    alt="App Store"
                    sx={{ height: { xs: 36, sm: 42, md: 48, tv: 56 }, width: "auto" }}
                  />
                </Box>
              ) : null}
              {data.playStoreUrl && mediaUrl(data.playStoreImage) ? (
                <Box component="a" href={data.playStoreUrl} target="_blank" rel="noopener noreferrer">
                  <Box
                    component="img"
                    src={mediaUrl(data.playStoreImage)}
                    alt="Play Store"
                    sx={{ height: { xs: 36, sm: 42, md: 48, tv: 56 }, width: "auto" }}
                  />
                </Box>
              ) : null}
            </Stack>
            {mediaUrl(data.qrImage) ? (
              <Box
                component="img"
                src={mediaUrl(data.qrImage)}
                alt="QR"
                sx={{
                  width: { xs: 140, sm: 180, md: 220, lg: 240, tv: 280 },
                  height: { xs: 140, sm: 180, md: 220, lg: 240, tv: 280 },
                  display: "block",
                  mb: 1.5,
                }}
              />
            ) : null}
            <Typography sx={{ color: "#5a6473", fontSize: { xs: 14, md: 16, tv: 18 } }}>{data.qrText}</Typography>
          </Box>
          {mediaUrl(data.sideImage) ? (
            <Box
              sx={{
                width: { xs: "100%", lg: "70%" },
                overflow: "hidden",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
            >
              <Box
                component="img"
                src={mediaUrl(data.sideImage)}
                alt={data.sideImage?.alternativeText || "App"}
                sx={{
                  width: "100%",
                  maxWidth: { xs: 420, sm: 560, md: 720, lg: "none", tv: 1100 },
                  display: "block",
                  transformOrigin: "center",
                }}
              />
            </Box>
          ) : null}
        </Stack>
      </Container>
    </Box>
  );
}
